<?php require_once __DIR__.'/includes/auth.php';$page_title='Referral Settings';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach(['commission_l1','commission_l2','commission_l3'] as $k){$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,is_public) VALUES(?,?,1) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),is_public=1');$s->execute([$k,(float)($_POST[$k]??0)]);}log_activity('Referral settings updated',(int)$admin['id']);flash('success','Referral settings saved.');go('referral-settings.php');}include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Referral Settings</h1><p>Only three configured levels are exposed to the public API.</p></div></div><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-grid"><div class="field"><label>LEVEL 1 %</label><input class="input" type="number" step=".01" name="commission_l1" value="<?=e((string)setting('commission_l1',11))?>"></div><div class="field"><label>LEVEL 2 %</label><input class="input" type="number" step=".01" name="commission_l2" value="<?=e((string)setting('commission_l2',3))?>"></div><div class="field"><label>LEVEL 3 %</label><input class="input" type="number" step=".01" name="commission_l3" value="<?=e((string)setting('commission_l3',2))?>"></div></div><button class="button button-primary">SAVE REFERRAL SETTINGS</button></form></section><?php include __DIR__.'/includes/footer.php';?>
